seen = set()
with open('i18n/textes-appli.tsv', 'w', encoding='utf-8') as f:
    f.write('fr\ten\tde\tes\tit\n')
    for r in ROWS:
        assert len(r) == 5 and r[0] not in seen and not any('\t' in x for x in r), r
        seen.add(r[0])
        f.write('\t'.join(r) + '\n')
print(len(ROWS), 'lignes')
